import ast, inspect, itertools, linecache, math, re

class pytest:
    class mark:
        def parametrize(names, rows):
            if isinstance(names, str):
                names = [n.strip() for n in names.split(",")]
            rows = [r if len(names) > 1 else (r,) for r in rows]
            def add(test):
                test.tables = [(names, rows)] + getattr(test, "tables", [])
                return test
            return add

    def fixture(f=None, **options):
        if f is None:
            return pytest.fixture
        f.is_fixture = True
        return f

    class approx:
        def __init__(self, expected, rel=None, abs=None):
            self.expected, self.rel, self.abs = expected, rel, abs
        def __eq__(self, actual):
            if isinstance(self.expected, (list, tuple)):
                return (isinstance(actual, (list, tuple)) and len(actual) == len(self.expected)
                        and all(a == pytest.approx(e, self.rel, self.abs) for a, e in zip(actual, self.expected)))
            if self.rel is None and self.abs is not None:
                gap = self.abs
            else:
                rel = 1e-6 if self.rel is None else self.rel
                gap = max(rel * abs(self.expected), 1e-12 if self.abs is None else self.abs)
            return abs(actual - self.expected) <= gap
        def __repr__(self):
            return f"approx({self.expected!r})"

    class raises:
        def __init__(self, error, match=None):
            self.error, self.match = error, match
        def __enter__(self):
            return self
        def __exit__(self, kind, err, tb):
            if kind is None:
                raise AssertionError(f"DID NOT RAISE {self.error.__name__}")
            if not issubclass(kind, self.error):
                return False  # a different error: the test fails with it
            if self.match and not re.search(self.match, str(err)):
                raise AssertionError(f"{self.match!r} does not match {str(err)!r}")
            return True

    def cases():  # each test once per row of its parametrize tables
        for name, test in list(globals().items()):
            if name.startswith("test") and inspect.isfunction(test):
                tables = getattr(test, "tables", [])
                for pick in itertools.product(*[range(len(rows)) for _, rows in tables]):
                    args, ids = {}, []
                    for (names, rows), k in zip(tables, pick):
                        args.update(zip(names, rows[k]))
                        ids += [str(v) if isinstance(v, (int, float, str)) else n + str(k)
                                for n, v in zip(names, rows[k])]
                    yield name + ("[" + "-".join(ids) + "]" if ids else ""), test, args

    def run_one(test, args):  # None when it passes, else the reason
        made = {}
        def give(name):
            if name not in args and name not in made:
                f = globals().get(name)
                if not getattr(f, "is_fixture", False):
                    raise LookupError(f"fixture '{name}' not found")
                made[name] = f(*map(give, inspect.signature(f).parameters))
            return args[name] if name in args else made[name]
        try:
            test(*map(give, inspect.signature(test).parameters))
        except AssertionError as e:
            return str(e) or pytest.explain(e.__traceback__)
        except Exception as e:
            return f"{type(e).__name__}: {e}"

    def explain(tb):  # the failing assert line, with both sides
        while tb.tb_next:
            tb = tb.tb_next
        fr, line = tb.tb_frame, linecache.getline(tb.tb_frame.f_code.co_filename, tb.tb_lineno).strip()
        try:
            t = ast.parse(line).body[0].test
            see = lambda n: repr(eval(ast.unparse(n), fr.f_globals, fr.f_locals))
            line += f"\nleft:  {see(t.left)}\nright: {see(t.comparators[0])}"
        except Exception:
            pass
        return line or "assert failed"

    def run(**versions):  # run every test, with any functions swapped in
        saved = {n: globals()[n] for n in versions}
        globals().update(versions)
        try:
            results = [(c, pytest.run_one(t, a)) for c, t, a in pytest.cases()]
        finally:
            globals().update(saved)
        for c, why in results:
            if why is None:
                print("PASSED", c)
            else:
                print("FAILED " + c + "\n    " + why.replace("\n", "\n    "))
        return results

    def main():
        results = pytest.run()
        failed = sum(why is not None for _, why in results)
        print(f"{len(results) - failed} passed, {failed} failed")
        return 5 if not results else 1 if failed else 0

    def outcome(**versions):
        results = pytest.run(**versions)
        return "no tests" if not results else "failed" if any(w is not None for _, w in results) else "passed"

    def count(test=None, fixture=None):
        return sum(1 for _, t, _ in pytest.cases() if test in (None, t.__name__)
                   and (fixture is None or fixture in inspect.signature(t).parameters))
