import statistics

def annualised_vol(returns):
    return statistics.stdev(returns) * math.sqrt(252)

r = [0.01, -0.02, 0.015, 0.005, -0.01]

def test_vol_doubles_when_returns_double():
    doubled = [2 * x for x in r]
    assert annualised_vol(doubled) == pytest.approx(2 * annualised_vol(r))

def test_vol_ignores_a_constant_shift():
    shifted = [x + 0.003 for x in r]
    assert annualised_vol(shifted) == pytest.approx(annualised_vol(r))

def test_vol_by_hand():
    # [0.01, -0.01]: mean 0, squared distances add to 0.0002, n - 1 = 1
    assert annualised_vol([0.01, -0.01]) == pytest.approx(math.sqrt(0.0002 * 252))
